export type CapabilityKey = "medicine" | "engineering" | "defense" | "food" | "exploration" | "science" | "psychology" | "communication" | "leadership" | "memory";

export type HostEvent = {
  title: string;
  message: string;
  event: string;
  pressure: CapabilityKey[];
  kind: "world" | "mutation" | "signal";
};

export type Catastrophe = {
  id: string;
  icon: string;
  title: string;
  summary: string;
  detail: string;
  opening: string;
  threat: string;
  resource: string;
  outside: string;
  mechanic: string;
  compatibility: string;
  visual: { image: string; accent: string; motif: string };
  backstory: {
    date: string; signal: string; format: string; headline: string;
    headlines: [string, string, string];
    chapterTitles: [string, string, string];
    chapters: [string, string, string];
    finalWords: string;
  };
  specialCards: HostEvent[];
  ending: { requirements: CapabilityKey[]; success: string; partial: string; failure: string };
};

