export function catastropheFromTitle(value: string) {
  return catastrophes.find((item) => value.startsWith(item.title)) ?? catastrophes[0];
}

export function getHostEvents(catastrophe: Catastrophe): HostEvent[] {
  return catastrophe.specialCards;
}
